'use strict';
const form=document.querySelector('#registration'),status=document.querySelector('#status'),button=document.querySelector('#submit');
let requestId=crypto.randomUUID();
form.addEventListener('input',()=>{requestId=crypto.randomUUID()});
fetch('courses.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(courses=>{const course=document.querySelector('#course');for(const c of courses){const option=document.createElement('option');option.value=c.slug;option.textContent=c.title;course.append(option)}const selected=new URLSearchParams(location.search).get('course');if(courses.some(c=>c.slug===selected))course.value=selected}).catch(()=>{status.textContent='Courses could not load. Please refresh.';button.disabled=true});
const result=new URLSearchParams(location.search).get('result');
if(result==='received')status.textContent='Your checkout submission was received. Registration and payment status will be confirmed after Stripe processes the payment. Monthly authorization does not itself confirm a successful charge.';
if(result==='cancelled')status.textContent='Checkout was cancelled. You can return to complete your registration.';
form.addEventListener('submit',async e=>{e.preventDefault();const api=(window.REGISTRATION_API_URL||'').replace(/\/$/,'');if(!api.startsWith('https://')){status.textContent='Online registration is not open yet. Please check back once checkout setup is complete.';return}button.disabled=true;status.textContent='Opening secure checkout…';const data=Object.fromEntries(new FormData(form));data.consent=form.elements.consent.checked;data.request_id=requestId;try{const r=await fetch(api+'/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const res=await r.json();if(!r.ok)throw Error(res.error||'Could not open checkout.');const url=new URL(res.url);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw Error('Invalid checkout destination.');location.assign(url.href)}catch(err){status.textContent=err.message;button.disabled=false}});
